/* Versão com gradiente para simular 3 círculos */
.timeline-container {
  position: relative;

}

/* Linha vertical */
.timeline-container::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 0;
  width: 3px;
  height: 100%;
  background-color: #ffffff;
  transform: translateX(-50%);
}

/* Círculos usando background-image no ::after */
.timeline-container::after {
  content: '';
  position: absolute;
  left: 50%;
  top: -3px;
  width: 16px;
  height: 101%;
  transform: translateX(-50%);
  background-image: 
    radial-gradient(circle, #ffffff 6px, transparent 6px), /* Topo */
    radial-gradient(circle, #ffffff 6px, transparent 6px), /* Centro */
    radial-gradient(circle, #ffffff 6px, transparent 6px); /* Base */
  background-position: 
    center top,
    center center,
    center bottom;
  background-size: 16px 16px;
  background-repeat: no-repeat;
  z-index: 1;
}

